        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeBridgeToolCall.write(item, into: &buf)
        }
    }

    static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [BridgeToolCall] {
        let len: Int32 = try readInt(&buf)
        var seq = [BridgeToolCall]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            try seq.append(FfiConverterTypeBridgeToolCall.read(from: &buf))
        }
        return seq
    }
}

